import { toast } from 'react-hot-toast';
import { exportToCSV } from './exportFormat';

export const getNoExportDataMessage = (entityName) =>
  `No ${entityName} found in the selected date range.`;

/**
 * Pull an array from common API response shapes.
 * @param {object|array} json - API response body
 * @param {...string} listKeys - e.g. 'exercises', 'users', 'badges'
 */
export const extractExportList = (json, ...listKeys) => {
  if (Array.isArray(json)) return json;

  for (const key of listKeys) {
    if (Array.isArray(json?.[key])) return json[key];
  }

  const data = json?.data;
  if (Array.isArray(data)) return data;

  if (data && typeof data === 'object') {
    for (const key of listKeys) {
      if (Array.isArray(data[key])) return data[key];
    }
  }

  return [];
};

/**
 * Export rows or show a clear empty-range error (replaces loading toast).
 */
export const performExport = async ({
  items,
  mapper,
  format,
  filename,
  sheetName = 'Sheet1',
  entityName,
  toastId,
  successMessage,
}) => {
  const rows = Array.isArray(items) ? items.filter((item) => item != null) : [];

  if (rows.length === 0) {
    toast.error(getNoExportDataMessage(entityName), { id: toastId });
    return false;
  }

  const exportData = typeof mapper === 'function' ? rows.map(mapper) : rows;

  if (!exportData.length) {
    toast.error(getNoExportDataMessage(entityName), { id: toastId });
    return false;
  }

  if (format === 'csv') {
    exportToCSV(exportData, filename);
  } else {
    const { exportToExcel } = await import('./exportExcel');
    await exportToExcel(exportData, filename, sheetName);
  }

  toast.success(
    successMessage || `${exportData.length} ${entityName} exported successfully`,
    { id: toastId },
  );
  return true;
};
