import React, { useState, useMemo, useEffect, useCallback } from "react";
import {
  Box,
  Typography,
  IconButton,
  Tooltip,
  alpha,
  useTheme,
  Stack,
} from "@mui/material";
import DisplayChip from "../../../components/DisplayChip";
import {
  Visibility as ViewIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  FormatQuote as QuoteIcon,
  MenuBook as CategoryIcon,
  Person as AuthorIcon,
  AccessTime as DateIcon,
} from "@mui/icons-material";
import DataTable from "../../../components/DataTable";
import DetailsModal from "../../../components/DetailsModal";
import ConfirmationModal from "../../../components/ConfirmationModal";
import QuoteModal from "../../../components/page_components/QuoteModal";
import { toast } from "react-hot-toast";
import StatusDropdown from "../../../components/StatusDropdown";
import { useSelector } from "react-redux";
import { mapQuoteExport } from "../../../utils/exportMappers";
import { extractExportList, performExport } from "../../../utils/exportHelpers";
import { useNavigate } from "react-router-dom";
import dayjs from "dayjs";


const BASE_URL = process.env.REACT_APP_API_BASE_URL;

// Dummy data removed, now using API

const Quotes = () => {
  const theme = useTheme();
  const navigate = useNavigate();
  const [quotes, setQuotes] = useState([]);

  const [isLoading, setIsLoading] = useState(false);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [orderBy, setOrderBy] = useState("created_at");
  const [order, setOrder] = useState("desc");
  const [searchTerm, setSearchTerm] = useState("");

  const token = useSelector((state) => state.auth.token);

  const [updatingStatusId, setUpdatingStatusId] = useState(null);

  const [openViewModal, setOpenViewModal] = useState(false);
  const [openDeleteModal, setOpenDeleteModal] = useState(false);
  const [openAddEditModal, setOpenAddEditModal] = useState(false);
  const [selectedQuote, setSelectedQuote] = useState(null);
  const [quoteToDelete, setQuoteToDelete] = useState(null);
  const [quoteToEdit, setQuoteToEdit] = useState(null);
  const [isSaving, setIsSaving] = useState(false);

  // Export Loading State
  const [isExporting, setIsExporting] = useState(false);

  const fetchQuotes = useCallback(async (apiPage, limit) => {
    if (!token) return;
    setIsLoading(true);
    try {
      const params = {
        page: apiPage,
        limit: limit,
        sort_by: orderBy,
        sort_order: order,
      };

      if (searchTerm) {
        params.q = searchTerm;
      }

      const queryParams = new URLSearchParams(params);

      const res = await fetch(`${BASE_URL}/motivational-quotes?${queryParams.toString()}`, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        toast.error(json.message || "Failed to fetch quotes");
        return;
      }

      // Robust handling of quotes data
      const fetchedQuotes = json.data?.quotes || (Array.isArray(json.data) ? json.data : (Array.isArray(json) ? json : []));
      setQuotes(fetchedQuotes);
      
      const total = json.data?.pagination?.total || json.pagination?.total || fetchedQuotes.length || 0;
      setTotalCount(total);
    } catch (err) {
      console.error("Error fetching quotes:", err);
      toast.error("Something went wrong while fetching quotes");
    } finally {
      setIsLoading(false);
    }
  }, [token, orderBy, order, searchTerm]);

  useEffect(() => {
    if (token) {
      fetchQuotes(page + 1, rowsPerPage);
    }
  }, [page, rowsPerPage, fetchQuotes, token]);

  const handleSortChange = (property) => {
    const isAsc = orderBy === property && order === "asc";
    setOrder(isAsc ? "desc" : "asc");
    setOrderBy(property);
    setPage(0);
  };

  const handleExport = async (dates, format) => {
    if (!token) return;
    setIsExporting(true);
    const toastId = toast.loading(`Exporting quotes as ${format.toUpperCase()}...`);
    
    try {
      const params = {
        sort_by: orderBy,
        sort_order: order,
        not_pagination: "true",
        start_date: dates.startDate.format('YYYY-MM-DD'),
        end_date: dates.endDate.format('YYYY-MM-DD'),
      };

      if (searchTerm) {
        params.q = searchTerm;
      }

      const queryParams = new URLSearchParams(params);

      const res = await fetch(`${BASE_URL}/motivational-quotes?${queryParams.toString()}`, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || "Failed to fetch quotes for export");
      }

      const items = extractExportList(json, 'quotes');
      const filename = `Motivational_Quotes_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

      await performExport({
        items,
        mapper: mapQuoteExport,
        format,
        filename,
        sheetName: 'Quotes',
        entityName: 'quotes',
        toastId,
      });
    } catch (err) {
      console.error("Export error:", err);
      toast.error(err.message || "Something went wrong while exporting", { id: toastId });
    } finally {
      setIsExporting(false);
    }
  };

  const handleStatusChange = async (id, newStatus) => {
    if (!token) return;
    setUpdatingStatusId(id);
    const toastId = toast.loading("Updating status...");
    try {
      const response = await fetch(`${BASE_URL}/motivational-quotes/${id}`, {
        method: "PATCH",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ is_active: newStatus === "active" }),
      });
      const result = await response.json();
      if (response.ok && !result.error) {
        toast.success("Status updated successfully", { id: toastId });
        setQuotes((prev) =>
          prev.map((q) =>
            q.id === id ? { ...q, is_active: newStatus === "active" } : q
          )
        );
      } else {
        toast.error(result.message || "Failed to update status", { id: toastId });
      }
    } catch (error) {
      toast.error("Connection error while updating status", { id: toastId });
    } finally {
      setUpdatingStatusId(null);
    }
  };

  const handleAddClick = () => {
    navigate('/quotes/add');
  };


  const handleEditClick = (quote) => {
    setQuoteToEdit(quote);
    setOpenAddEditModal(true);
  };

  const handleViewDetails = (quote) => {
    setSelectedQuote(quote);
    setOpenViewModal(true);
  };

  const handleDeleteClick = (quote) => {
    setQuoteToDelete(quote);
    setOpenDeleteModal(true);
  };

  const handleConfirmDelete = async () => {
    if (!quoteToDelete || !token) return;
    const toastId = toast.loading("Deleting quote...");
    try {
      const response = await fetch(`${BASE_URL}/motivational-quotes/${quoteToDelete.id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      const result = await response.json();
      if (response.ok && !result.error) {
        toast.success("Quote deleted successfully!", { id: toastId });
        fetchQuotes(page + 1, rowsPerPage);
      } else {
        toast.error(result.message || "Delete failed", { id: toastId });
      }
    } catch (error) {
      toast.error("Server error", { id: toastId });
    } finally {
      setOpenDeleteModal(false);
      setQuoteToDelete(null);
    }
  };

  const handleSaveQuote = async (formData, keepOpen = false) => {
    if (!token) return false;
    setIsSaving(true);
    const toastId = toast.loading(`${quoteToEdit ? "Updating" : "Adding"} quote...`);
    try {
      const url = quoteToEdit
        ? `${BASE_URL}/motivational-quotes/${quoteToEdit.id}`
        : `${BASE_URL}/motivational-quotes`;

      const response = await fetch(url, {
        method: quoteToEdit ? "PATCH" : "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      const result = await response.json();
      if (response.ok && !result.error) {
        toast.success(`Quote ${quoteToEdit ? "Updated" : "Added"} Successfully!`, { id: toastId });
        if (!keepOpen) {
          setOpenAddEditModal(false);
          setQuoteToEdit(null);
        }
        fetchQuotes(page + 1, rowsPerPage);
        return true;
      } else {
        toast.error(result.message || "Save failed", { id: toastId });
        return false;
      }
    } catch (error) {
      toast.error("Internal server error", { id: toastId });
      return false;
    } finally {
      setIsSaving(false);
    }
  };

  const columns = [
    {
      id: "text",
      label: "Quote Content",
      render: (row) => (
        <Box sx={{ maxWidth: 400 }}>
          <Typography
            sx={{
              color: "#FFFFFF",
              fontWeight: 500,
              fontSize: "0.875rem",
              display: "-webkit-box",
              WebkitLineClamp: 2,
              WebkitBoxOrient: "vertical",
              overflow: "hidden",
            }}
          >
            "{row.text}"
          </Typography>
        </Box>
      ),
    },
    {
      id: "author",
      label: "Author",
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <AuthorIcon sx={{ fontSize: 16, color: theme.palette.primary.main }} />
          <Typography sx={{ color: "#8B8D97", fontSize: "0.875rem" }}>
            {row.author}
          </Typography>
        </Box>
      ),
    },
    {
      id: "frequency",
      label: "Frequency",
      render: (row) => (
        <DisplayChip
          label={row.frequency || "daily"}
          size="small"
          sx={{
            textTransform: "capitalize",
            bgcolor: alpha(theme.palette.primary.main, 0.1),
            color: theme.palette.primary.main,
            fontWeight: 600,
            fontSize: "0.75rem",
          }}
        />
      ),
    },
    {
      id: "status",
      label: "Status",
      render: (row) => (
        <StatusDropdown
          status={row.is_active ? "active" : "inactive"}
          options={[
            { label: "Active", value: "active", color: "#4CC66E" },
            { label: "Inactive", value: "inactive", color: "#FF5050" },
          ]}
          onStatusChange={(newStatus) => handleStatusChange(row.id, newStatus)}
          isLoading={updatingStatusId === row.id}
        />
      ),
    },
    {
      id: "created_at",
      label: "Added Date",
      render: (row) => (
        <Typography sx={{ color: "#8B8D97", fontSize: "0.875rem" }}>
          {new Date(row.created_at).toLocaleDateString()}
        </Typography>
      ),
    },
    {
      id: "actions",
      label: "Actions",
      render: (row) => (
        <Box sx={{ display: "flex", gap: 1 }}>
          <Tooltip title="View Details">
            <IconButton
              size="small"
              onClick={() => handleViewDetails(row)}
              sx={{
                color: "#9F6EDA",
                bgcolor: alpha("#9F6EDA", 0.1),
                "&:hover": { bgcolor: alpha("#9F6EDA", 0.2) },
              }}
            >
              <ViewIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip title="Edit">
            <IconButton
              size="small"
              onClick={() => handleEditClick(row)}
              sx={{
                color: "#9F6EDA",
                bgcolor: alpha("#9F6EDA", 0.1),
                "&:hover": { bgcolor: alpha("#9F6EDA", 0.2) },
              }}
            >
              <EditIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip title="Delete">
            <IconButton
              size="small"
              onClick={() => handleDeleteClick(row)}
              sx={{
                color: "#FF5050",
                bgcolor: alpha("#FF5050", 0.1),
                "&:hover": { bgcolor: alpha("#FF5050", 0.2) },
              }}
            >
              <DeleteIcon fontSize="small" />
            </IconButton>
          </Tooltip>
        </Box>
      ),
    },
  ];

  const detailsData = useMemo(() => {
    if (!selectedQuote) return [];
    return [
      { label: "Author", value: selectedQuote.author },
      { label: "Frequency", value: selectedQuote.frequency || "daily" },
      { label: "Status", value: selectedQuote.is_active ? "Active" : "Inactive" },
      { label: "Quote", value: selectedQuote.text },
      {
        label: "Date Added",
        value: new Date(selectedQuote.created_at).toLocaleString(),
      },
    ];
  }, [selectedQuote]);

  return (
    <Box sx={{ p: { xs: 1, md: 3 } }}>
      <DataTable
        title="Motivational Quotes"
        columns={columns}
        data={quotes}
        isLoading={isLoading}
        onAddClick={handleAddClick}
        addLabel="Add New Quote"
        searchTerm={searchTerm}
        onSearchChange={(val) => {
          setSearchTerm(val);
          setPage(0);
        }}
        onExport={handleExport}
        isExporting={isExporting}
        orderBy={orderBy}
        order={order}
        onSortChange={handleSortChange}
        pagination={{
          page: page,
          rowsPerPage: rowsPerPage,
          totalCount: totalCount,
          onPageChange: (_, newPage) => setPage(newPage),
          onRowsPerPageChange: (e) => {
            setRowsPerPage(parseInt(e.target.value, 10));
            setPage(0);
          },
        }}
        emptyTitle="No quotes found"
        />

      {selectedQuote && (
        <DetailsModal
          open={openViewModal}
          onClose={() => setOpenViewModal(false)}
          title="Quote Details"
          data={detailsData}
          maxWidth="sm"
        />
      )}

      <QuoteModal
        open={openAddEditModal}
        onClose={() => setOpenAddEditModal(false)}
        onSubmit={handleSaveQuote}
        initialData={quoteToEdit}
        loading={isSaving}
      />

      <ConfirmationModal
        open={openDeleteModal}
        onClose={() => setOpenDeleteModal(false)}
        onConfirm={handleConfirmDelete}
        title="Delete Quote?"
        message="Are you sure you want to delete this quote? This action cannot be undone."
        confirmText="Delete"
        confirmColor="error"
      />
    </Box>
  );
};

export default Quotes;
